public record JobId(String value) {
    public JobId {
        if (value.length() < 8 || value.length() > 64)
            throw new IllegalArgumentException("job id must be 8 to 64 characters");
        if (!value.matches("[A-Za-z0-9_-]+"))
            throw new IllegalArgumentException("bad character in job id: " + value);
    }
}

// every new JobId(...) is an object with identity
static PrintJob findJob(JobId id) { ... }   // JVM: findJob(JobId)

