value class Isbn(val value: String) {
    init {
        require(value.length == 13 && value.all { it in '0'..'9' }) { "ISBN must be 13 digits: $value" }
        require(value.startsWith("978") || value.startsWith("979")) { "ISBN must start with 978 or 979: $value" }
    }
}

